import debounce from "lodash.debounce";
export const createProgressLogger = ({ total, message, unitLabel, prefix, debounceMs = 5000, silent = false, log = console.info, }) => {
    let current = 0;
    let lastProgressLog = -1;
    const formatMessage = () => `${prefix ? `${prefix}: ` : ""}${message}: ${current}/${total} ${unitLabel}`;
    const emitLog = () => {
        if (current === lastProgressLog) {
            return;
        }
        log(formatMessage());
        lastProgressLog = current;
    };
    const debouncedEmitLog = debounce(emitLog, debounceMs, { maxWait: debounceMs });
    const flushLog = () => {
        debouncedEmitLog.cancel();
        emitLog();
    };
    const logProgress = (force = false) => {
        if (silent) {
            return;
        }
        if (force) {
            flushLog();
            return;
        }
        if (current === total) {
            flushLog();
            return;
        }
        debouncedEmitLog();
    };
    return {
        log: logProgress,
        increment: (delta = 1) => {
            current = Math.min(total, current + delta);
            if (silent) {
                return;
            }
            if (current === total) {
                flushLog();
                return;
            }
            logProgress();
        },
        getCurrent: () => current,
        cancel: () => debouncedEmitLog.cancel(),
    };
};
